$site=getenv('MERCATO_TEST_SITE');if(!$site){echo "Mercato headless API integration test skipped (set MERCATO_TEST_SITE).\n";exit(0);}require $site.'/wire/core/ProcessWire.php';$config=ProcessWire::buildConfig($site);$config->dbHost='localhost';$wire=new ProcessWire($config);$wire->users->setCurrentUser($wire->users->get('template=user, roles.name=superuser'));$wire->set('page',$wire->pages->get('/'));/** @var Mercato $commerce */$commerce=$wire->modules->get('Mercato');$service=$commerce->headlessApiService();$product=null;foreach($wire->pages->find('template=mrc-product,mrc_product_status=active,mrc_product_type=physical,include=all')as$candidate){if($commerce->variantService()->getDefinition($candidate)['variants']===[]){$product=$candidate;break;}}if(!$product instanceof Page||!$product->id)throw new \RuntimeException('Non-variant physical fixture product missing.');$originalStock=(int)$product->mrc_stock;$originalPrice=(float)$product->mrc_price;$originalCart=$commerce->cart()->toArray();$originalMethods=$commerce->enabled_payment_methods;$commerce->set('enabled_payment_methods',['demo']);$order=null;$nonce=bin2hex(random_bytes(6));
$customer=['first_name'=>'Native','last_name'=>'Fixture','email'=>'api-'.$nonce.'@example.test','address'=>'API Street','city'=>'Test City','zip'=>'10001','country'=>'US'];$options=['fulfilment_method'=>'carrier_delivery','payment_method'=>'demo','policy_accepted'=>true];$body=['items'=>[['product_id'=>(int)$product->id,'quantity'=>1]],'customer'=>$customer,'options'=>$options];
