 $created=$service->createCheckout($body,'create-'.$nonce);$replayed=$service->createCheckout($body,'create-'.$nonce);if($created['id']!==$replayed['id']||empty($created['token']))throw new \RuntimeException('Checkout creation was not idempotent.');$order=$wire->pages->get('template=mrc-order,include=all,mrc_api_checkout_id='.$wire->sanitizer->selectorValue($created['id']));if(!$order->id)throw new \RuntimeException('Opaque checkout was not persisted.');
 $notFound=false;try{$service->checkout($created['id'],'wrong-token');}catch(MercatoHeadlessApiException $e){$notFound=$e->httpStatus===404;}if(!$notFound)throw new \RuntimeException('Invalid token disclosed checkout state.');
 $first=$service->complete($created['id'],$created['token'],[],'complete-'.$nonce);$second=$service->complete($created['id'],$created['token'],[],'complete-'.$nonce);if(empty($first['payment_complete'])||empty($second['replayed']))throw new \RuntimeException('Completion replay was not idempotent.');$public=$service->order($created['order_id'],$created['token']);if(($public['payment_status']??'')!==MercatoPaymentStatus::PAID||isset($public['email'])||isset($public['address']))throw new \RuntimeException('Order API status or privacy contract failed.');
