 $product->of(false);$product->mrc_stock=0;$wire->pages->save($product);$blocked=false;try{$service->createCheckout($body,'stock-'.$nonce);}catch(WireException $e){$blocked=str_contains(strtolower($e->getMessage()),'stock')||str_contains(strtolower($e->getMessage()),'available');}if(!$blocked)throw new \RuntimeException('Insufficient stock checkout was accepted.');
}finally{$commerce->set('enabled_payment_methods',$originalMethods);$commerce->cart($originalCart);$product->of(false);$product->mrc_price=$originalPrice;$product->mrc_stock=$originalStock;$wire->pages->save($product);if($order instanceof Page&&$order->id){$order->of(false);$wire->pages->delete($order,true);}}
